import numpy as np


def no_curation(n, k=4):
    """随机选 1 个"""
    return np.random.randint(0, k, size=n)


def single_reward(quality_scores):
    """选 ArmoRM 分数最高的"""
    return np.argmax(quality_scores, axis=1)


def fixed_weight(quality_norm, diversity_norm, complexity_norm, weights=None):
    """固定等权加权，选总分最高的"""
    if weights is None:
        weights = [1/3, 1/3, 1/3]
    combined = (weights[0] * quality_norm +
                weights[1] * diversity_norm +
                weights[2] * complexity_norm)
    return np.argmax(combined, axis=1)


def carr_curate(quality_norm, diversity_norm, complexity_norm, weights):
    """CARR 动态权重加权，选总分最高的"""
    combined = (weights[0] * quality_norm +
                weights[1] * diversity_norm +
                weights[2] * complexity_norm)
    return np.argmax(combined, axis=1)
